  static const int GESTURE_SNAP = 6;

  /// < The mobile device is tilted
  static const int GESTURE_TILT = 7;

  /// < The mobile device is flipped from face to back
  static const int GESTURE_TURN_FACE_DOWN = 8;

  /// < The wearable device is moved and faced up
  static const int GESTURE_WRIST_UP = 9;
}

/// **Deprecated:** Deprecated since 6.0.
