  static const int GESTURE_SNAP_X_NEGATIVE = 1;

  /// < Detected +X snap
  static const int GESTURE_SNAP_X_POSITIVE = 2;

  /// < Detected -Y snap
  static const int GESTURE_SNAP_Y_NEGATIVE = 3;

  /// < Detected +Y snap
  static const int GESTURE_SNAP_Y_POSITIVE = 4;

